149	
150	  private static final float MAX_AVG_VARIANCE = 0.25f;
151	  private static final float MAX_INDIVIDUAL_VARIANCE = 0.7f;
152	
153	  private static final int CODE_SHIFT = 98;
154	
155	  private static final int CODE_CODE_C = 99;
156	  private static final int CODE_CODE_B = 100;
157	  private static final int CODE_CODE_A = 101;
158	
159	  private static final int CODE_FNC_1 = 102;
160	  private static final int CODE_FNC_2 = 97;
161	  private static final int CODE_FNC_3 = 96;
162	  private static final int CODE_FNC_4_A = 101;
163	  private static final int CODE_FNC_4_B = 100;
164	
165	  private static final int CODE_START_A = 103;
166	  private static final int CODE_START_B = 104;
167	  private static final int CODE_START_C = 105;
168	  private static final int CODE_STOP = 106;
169	
170	  private static int[] findStartPattern(BitArray row) throws NotFoundException {
171	    int width = row.getSize();
172	    int rowOffset = row.getNextSet(0);
173	
174	    int counterPosition = 0;
175	    int[] counters = new int[6];
176	    int patternStart = rowOffset;
177	    boolean isWhite = false;
178	    int patternLength = counters.length;
179	
180	    for (int i = rowOffset; i < width; i++) {
181	      if (row.get(i) != isWhite) {
182	        counters[counterPosition]++;
183	      } else {
184	        if (counterPosition == patternLength - 1) {
185	          float bestVariance = MAX_AVG_VARIANCE;
186	          int bestMatch = -1;
187	          for (int startCode = CODE_START_A; startCode <= CODE_START_C; startCode++) {
188	            float variance = patternMatchVariance(counters, CODE_PATTERNS[startCode],
189	                MAX_INDIVIDUAL_VARIANCE);
190	            if (variance < bestVariance) {
191	              bestVariance = variance;
192	              bestMatch = startCode;
193	            }
194	          }
195	          // Look for whitespace before start pattern, >= 50% of width of start pattern
196	          if (bestMatch >= 0 &&
197	              row.isRange(Math.max(0, patternStart - (i - patternStart) / 2), patternStart, false)) {
198	            return new int[]{patternStart, i, bestMatch};
199	          }
200	          patternStart += counters[0] + counters[1];
201	          System.arraycopy(counters, 2, counters, 0, counterPosition - 1);
202	          counters[counterPosition - 1] = 0;
203	          counters[counterPosition] = 0;
204	          counterPosition--;
205	        } else {
206	          counterPosition++;
207	        }
208	        counters[counterPosition] = 1;
209	        isWhite = !isWhite;
210	      }
211	    }
212	    throw NotFoundException.getNotFoundInstance();
213	  }
214	
215	  private static int decodeCode(BitArray row, int[] counters, int rowOffset)
216	      throws NotFoundException {
217	    recordPattern(row, rowOffset, counters);
218	    float bestVariance = MAX_AVG_VARIANCE; // worst variance we'll accept
219	    int bestMatch = -1;
220	    for (int d = 0; d < CODE_PATTERNS.length; d++) {
221	      int[] pattern = CODE_PATTERNS[d];
222	      float variance = patternMatchVariance(counters, pattern, MAX_INDIVIDUAL_VARIANCE);
223	      if (variance < bestVariance) {
224	        bestVariance = variance;
225	        bestMatch = d;
226	      }
227	    }
228	    // TODO We're overlooking the fact that the STOP pattern has 7 values, not 6.
229	    if (bestMatch >= 0) {
230	      return bestMatch;
231	    } else {
232	      throw NotFoundException.getNotFoundInstance();
233	    }
234	  }
235	
236	  @Override
237	  public Result decodeRow(int rowNumber, BitArray row, Map<DecodeHintType,?> hints)
238	      throws NotFoundException, FormatException, ChecksumException {
239	
240	    boolean convertFNC1 = hints != null && hints.containsKey(DecodeHintType.ASSUME_GS1);
241	
242	    int symbologyModifier = 0;
243	    boolean readerInit = false;
244	
245	    int[] startPatternInfo = findStartPattern(row);
246	    int startCode = startPatternInfo[2];
247	
248	    List<Byte> rawCodes = new ArrayList<>(20);
249	    rawCodes.add((byte) startCode);
250	
251	    int codeSet;
252	    switch (startCode) {
253	      case CODE_START_A:
254	        codeSet = CODE_CODE_A;
255	        break;
256	      case CODE_START_B:
257	        codeSet = CODE_CODE_B;
258	        break;
259	      case CODE_START_C:
260	        codeSet = CODE_CODE_C;
261	        break;
262	      default:
263	        throw FormatException.getFormatInstance();
264	    }
265	
266	    boolean done = false;
267	    boolean isNextShifted = false;
268	
269	    StringBuilder result = new StringBuilder(20);
270	
271	    int lastStart = startPatternInfo[0];
272	    int nextStart = startPatternInfo[1];
273	    int[] counters = new int[6];
274	
275	    int lastCode = 0;
276	    int code = 0;
277	    int checksumTotal = startCode;
278	    int multiplier = 0;
279	    int lastResultLength = 0;
280	    int lastSymbologyModifier = symbologyModifier;
281	    boolean lastReaderInit = readerInit;
282	    boolean upperMode = false;
283	    boolean shiftUpperMode = false;
284	
285	    while (!done) {
286	
287	      boolean unshift = isNextShifted;
288	      isNextShifted = false;
289	
290	      // Save off last code
291	      lastCode = code;
292	
293	      // Decode another code from image
294	      code = decodeCode(row, counters, nextStart);
295	
296	      rawCodes.add((byte) code);
297	
298	      // Save the output in case this code is the checksum.
299	      if (code != CODE_STOP) {
300	        lastResultLength = result.length();
301	        lastSymbologyModifier = symbologyModifier;
302	        lastReaderInit = readerInit;
303	        multiplier++;
304	        checksumTotal += multiplier * code;
305	      }
306	
307	      // Advance to where the next code will to start
308	      lastStart = nextStart;
309	      for (int counter : counters) {
310	        nextStart += counter;
311	      }
312	
313	      // Take care of illegal start codes
314	      switch (code) {
315	        case CODE_START_A:
316	        case CODE_START_B:
317	        case CODE_START_C:
318	          throw FormatException.getFormatInstance();
319	      }
320	
321	      switch (codeSet) {
322	
323	        case CODE_CODE_A:
324	          if (code < 64) {
325	            if (shiftUpperMode == upperMode) {
326	              result.append((char) (' ' + code));
327	            } else {
328	              result.append((char) (' ' + code + 128));
329	            }
330	            shiftUpperMode = false;
331	          } else if (code < 96) {
332	            if (shiftUpperMode == upperMode) {
333	              result.append((char) (code - 64));
334	            } else {
335	              result.append((char) (code + 64));
336	            }
337	            shiftUpperMode = false;
338	          } else {
339	            switch (code) {
340	              case CODE_FNC_1:
341	                if (result.length() == 0) { // FNC1 at first or second character determines the symbology
342	                  symbologyModifier = 1;
343	                } else if (result.length() == 1) {
344	                  symbologyModifier = 2;
345	                }
346	                if (convertFNC1) {
347	                  if (result.length() == 0) {
348	                    // GS1 specification 5.4.3.7. and 5.4.6.4. If the first char after the start code
349	                    // is FNC1 then this is GS1-128. We add the symbology identifier.
350	                    result.append("]C1");
351	                  } else {
352	                    // GS1 specification 5.4.7.5. Every subsequent FNC1 is returned as ASCII 29 (GS)
353	                    result.append((char) 29);
354	                  }
355	                }
356	                break;
357	              case CODE_FNC_2:
358	                symbologyModifier = 4;
359	                break;
360	              case CODE_FNC_3:
361	                readerInit = true;
362	                break;
363	              case CODE_FNC_4_A:
364	                if (!upperMode && shiftUpperMode) {
365	                  upperMode = true;
366	                  shiftUpperMode = false;
367	                } else if (upperMode && shiftUpperMode) {
368	                  upperMode = false;
369	                  shiftUpperMode = false;
370	                } else {
371	                  shiftUpperMode = true;
372	                }
373	                break;
374	              case CODE_SHIFT:
375	                isNextShifted = true;
376	                codeSet = CODE_CODE_B;
377	                break;
378	              case CODE_CODE_B:
379	                codeSet = CODE_CODE_B;
380	                break;
381	              case CODE_CODE_C:
382	                codeSet = CODE_CODE_C;
383	                break;
384	              case CODE_STOP:
385	                done = true;
386	                break;
387	            }
388	          }
389	          break;
390	        case CODE_CODE_B:
391	          if (code < 96) {
392	            if (shiftUpperMode == upperMode) {
393	              result.append((char) (' ' + code));
394	            } else {
395	              result.append((char) (' ' + code + 128));
396	            }
397	            shiftUpperMode = false;
398	          } else {
399	            switch (code) {
400	              case CODE_FNC_1:
401	                if (result.length() == 0) { // FNC1 at first or second character determines the symbology
402	                  symbologyModifier = 1;
403	                } else if (result.length() == 1) {
404	                  symbologyModifier = 2;
405	                }
406	                if (convertFNC1) {
407	                  if (result.length() == 0) {
408	                    // GS1 specification 5.4.3.7. and 5.4.6.4. If the first char after the start code
409	                    // is FNC1 then this is GS1-128. We add the symbology identifier.
410	                    result.append("]C1");
411	                  } else {
412	                    // GS1 specification 5.4.7.5. Every subsequent FNC1 is returned as ASCII 29 (GS)
413	                    result.append((char) 29);
414	                  }
415	                }
416	                break;
417	              case CODE_FNC_2:
418	                symbologyModifier = 4;
419	                break;
420	              case CODE_FNC_3:
421	                readerInit = true;
422	                break;
423	              case CODE_FNC_4_B:
424	                if (!upperMode && shiftUpperMode) {
425	                  upperMode = true;
426	                  shiftUpperMode = false;
427	                } else if (upperMode && shiftUpperMode) {
428	                  upperMode = false;
429	                  shiftUpperMode = false;
430	                } else {
431	                  shiftUpperMode = true;
432	                }
433	                break;
434	              case CODE_SHIFT:
435	                isNextShifted = true;
436	                codeSet = CODE_CODE_A;
437	                break;
438	              case CODE_CODE_A:
439	                codeSet = CODE_CODE_A;
440	                break;
441	              case CODE_CODE_C:
442	                codeSet = CODE_CODE_C;
443	                break;
444	              case CODE_STOP:
445	                done = true;
446	                break;
447	            }
448	          }
449	          break;
450	        case CODE_CODE_C:
451	          if (code < 100) {
452	            if (code < 10) {
453	              result.append('0');
454	            }
455	            result.append(code);
456	          } else {
457	            switch (code) {
458	              case CODE_FNC_1:
459	                if (result.length() == 0) { // FNC1 at first or second character determines the symbology
460	                  symbologyModifier = 1;
461	                } else if (result.length() == 1) {
462	                  symbologyModifier = 2;
463	                }
464	                if (convertFNC1) {
465	                  if (result.length() == 0) {
466	                    // GS1 specification 5.4.3.7. and 5.4.6.4. If the first char after the start code
467	                    // is FNC1 then this is GS1-128. We add the symbology identifier.
468	                    result.append("]C1");
469	                  } else {
470	                    // GS1 specification 5.4.7.5. Every subsequent FNC1 is returned as ASCII 29 (GS)
471	                    result.append((char) 29);
472	                  }
473	                }
474	                break;
475	              case CODE_CODE_A:
476	                codeSet = CODE_CODE_A;
477	                break;
478	              case CODE_CODE_B:
479	                codeSet = CODE_CODE_B;
480	                break;
481	              case CODE_STOP:
482	                done = true;
483	                break;
484	            }
485	          }
486	          break;
487	      }
488	
489	      // Unshift back to another code set if we were shifted
490	      if (unshift) {
491	        codeSet = codeSet == CODE_CODE_A ? CODE_CODE_B : CODE_CODE_A;
492	      }
493	
494	    }
495	
496	    int lastPatternSize = nextStart - lastStart;
497	
498	    // Check for ample whitespace following pattern, but, to do this we first need to remember that
499	    // we fudged decoding CODE_STOP since it actually has 7 bars, not 6. There is a black bar left
500	    // to read off. Would be slightly better to properly read. Here we just skip it:
501	    nextStart = row.getNextUnset(nextStart);
502	    if (!row.isRange(nextStart,
503	                     Math.min(row.getSize(), nextStart + (nextStart - lastStart) / 2),
504	                     false)) {
505	      throw NotFoundException.getNotFoundInstance();
506	    }
507	
508	    // Pull out from sum the value of the penultimate check code
509	    checksumTotal -= multiplier * lastCode;
510	    // lastCode is the checksum then:
511	    if (checksumTotal % 103 != lastCode) {
512	      throw ChecksumException.getChecksumInstance();
513	    }
514	
515	    int resultLength = result.length();
516	    if (resultLength == 0) {
517	      // false positive
518	      throw NotFoundException.getNotFoundInstance();
519	    }
520	
521	    // Discard the checksum's text and function code effects.
522	    result.setLength(lastResultLength);
523	    symbologyModifier = lastSymbologyModifier;
524	    readerInit = lastReaderInit;
525	
526	    float left = (startPatternInfo[1] + startPatternInfo[0]) / 2.0f;
527	    float right = lastStart + lastPatternSize / 2.0f;
528	
529	    int rawCodesSize = rawCodes.size();
530	    byte[] rawBytes = new byte[rawCodesSize];
531	    for (int i = 0; i < rawCodesSize; i++) {
532	      rawBytes[i] = rawCodes.get(i);
533	    }
534	
535	    Result resultObject = new Result(
536	        result.toString(),
537	        rawBytes,
538	        new ResultPoint[]{
539	            new ResultPoint(left, rowNumber),
540	            new ResultPoint(right, rowNumber)},
541	        BarcodeFormat.CODE_128);
542	
543	    resultObject.putMetadata(ResultMetadataType.SYMBOLOGY_IDENTIFIER, "]C" + symbologyModifier);
544	    resultObject.putMetadata(ResultMetadataType.READER_INIT, readerInit);
545	
546	    return resultObject;
547	  }
548	
549	}
