310	  /**
311	   * @param row row of black/white values to search
312	   * @param rowOffset position to start search
313	   * @param whiteFirst if true, indicates that the pattern specifies white/black/white/...
314	   * pixel counts, otherwise, it is interpreted as black/white/black/...
315	   * @param pattern pattern of counts of number of black and white pixels that are being
316	   * searched for as a pattern
317	   * @param counters array of counters, as long as pattern, to re-use
318	   * @return start/end horizontal offset of guard pattern, as an array of two ints
319	   * @throws NotFoundException if pattern is not found
320	   */
321	  private static int[] findGuardPattern(BitArray row,
322	                                        int rowOffset,
323	                                        boolean whiteFirst,
324	                                        int[] pattern,
325	                                        int[] counters) throws NotFoundException {
326	    int width = row.getSize();
327	    rowOffset = whiteFirst ? row.getNextUnset(rowOffset) : row.getNextSet(rowOffset);
328	    int counterPosition = 0;
329	    int patternStart = rowOffset;
330	    int patternLength = pattern.length;
331	    boolean isWhite = whiteFirst;
332	    for (int x = rowOffset; x < width; x++) {
333	      if (row.get(x) != isWhite) {
334	        counters[counterPosition]++;
335	      } else {
336	        if (counterPosition == patternLength - 1) {
337	          if (patternMatchVariance(counters, pattern, MAX_INDIVIDUAL_VARIANCE) < MAX_AVG_VARIANCE) {
338	            return new int[]{patternStart, x};
339	          }
340	          patternStart += counters[0] + counters[1];
341	          System.arraycopy(counters, 2, counters, 0, counterPosition - 1);
342	          counters[counterPosition - 1] = 0;
343	          counters[counterPosition] = 0;
344	          counterPosition--;
345	        } else {
346	          counterPosition++;
347	        }
348	        counters[counterPosition] = 1;
349	        isWhite = !isWhite;
350	      }
351	    }
352	    throw NotFoundException.getNotFoundInstance();
353	  }
354	
355	  /**
356	   * Attempts to decode a single UPC/EAN-encoded digit.
357	   *
358	   * @param row row of black/white values to decode
359	   * @param counters the counts of runs of observed black/white/black/... values
360	   * @param rowOffset horizontal offset to start decoding from
361	   * @param patterns the set of patterns to use to decode -- sometimes different encodings
362	   * for the digits 0-9 are used, and this indicates the encodings for 0 to 9 that should
363	   * be used
364	   * @return horizontal offset of first pixel beyond the decoded digit
365	   * @throws NotFoundException if digit cannot be decoded
366	   */
367	  static int decodeDigit(BitArray row, int[] counters, int rowOffset, int[][] patterns)
368	      throws NotFoundException {
369	    recordPattern(row, rowOffset, counters);
370	    float bestVariance = MAX_AVG_VARIANCE; // worst variance we'll accept
371	    int bestMatch = -1;
372	    int max = patterns.length;
373	    for (int i = 0; i < max; i++) {
374	      int[] pattern = patterns[i];
375	      float variance = patternMatchVariance(counters, pattern, MAX_INDIVIDUAL_VARIANCE);
376	      if (variance < bestVariance) {
377	        bestVariance = variance;
378	        bestMatch = i;
379	      }
380	    }
381	    if (bestMatch >= 0) {
382	      return bestMatch;
383	    } else {
384	      throw NotFoundException.getNotFoundInstance();
385	    }
386	  }
387	
388	  /**
389	   * Get the format of this decoder.
390	   *
391	   * @return The 1D format.
392	   */
393	  abstract BarcodeFormat getBarcodeFormat();
394	
395	  /**
396	   * Subclasses override this to decode the portion of a barcode between the start
397	   * and end guard patterns.
398	   *
399	   * @param row row of black/white values to search
400	   * @param startRange start/end offset of start guard pattern
401	   * @param resultString {@link StringBuilder} to append decoded chars to
402	   * @return horizontal offset of first pixel after the "middle" that was decoded
403	   * @throws NotFoundException if decoding could not complete successfully
404	   */
405	  protected abstract int decodeMiddle(BitArray row,
406	                                      int[] startRange,
407	                                      StringBuilder resultString) throws NotFoundException;
408	
409	}
