17	package com.google.zxing.multi;
18	
19	import com.google.zxing.BinaryBitmap;
20	import com.google.zxing.ChecksumException;
21	import com.google.zxing.DecodeHintType;
22	import com.google.zxing.FormatException;
23	import com.google.zxing.NotFoundException;
24	import com.google.zxing.Reader;
25	import com.google.zxing.Result;
26	import com.google.zxing.ResultPoint;
27	
28	import java.util.Map;
29	
30	/**
31	 * This class attempts to decode a barcode from an image, not by scanning the whole image,
32	 * but by scanning subsets of the image. This is important when there may be multiple barcodes in
33	 * an image, and detecting a barcode may find parts of multiple barcode and fail to decode
34	 * (e.g. QR Codes). Instead this scans the four quadrants of the image -- and also the center
35	 * 'quadrant' to cover the case where a barcode is found in the center.
36	 *
37	 * @see GenericMultipleBarcodeReader
38	 */
39	public final class ByQuadrantReader implements Reader {
40	
41	  private final Reader delegate;
42	
43	  public ByQuadrantReader(Reader delegate) {
44	    this.delegate = delegate;
45	  }
46	
47	  @Override
48	  public Result decode(BinaryBitmap image)
49	      throws NotFoundException, ChecksumException, FormatException {
50	    return decode(image, null);
51	  }
52	
53	  @Override
54	  public Result decode(BinaryBitmap image, Map<DecodeHintType,?> hints)
55	      throws NotFoundException, ChecksumException, FormatException {
56	
57	    int width = image.getWidth();
58	    int height = image.getHeight();
59	    int halfWidth = width / 2;
60	    int halfHeight = height / 2;
61	
62	    try {
63	      // No need to call makeAbsolute as results will be relative to original top left here
64	      return delegate.decode(image.crop(0, 0, halfWidth, halfHeight), hints);
65	    } catch (NotFoundException re) {
66	      // continue
67	    }
68	
69	    try {
70	      Result result = delegate.decode(image.crop(halfWidth, 0, halfWidth, halfHeight), hints);
71	      makeAbsolute(result.getResultPoints(), halfWidth, 0);
72	      return result;
73	    } catch (NotFoundException re) {
74	      // continue
75	    }
76	
77	    try {
78	      Result result = delegate.decode(image.crop(0, halfHeight, halfWidth, halfHeight), hints);
79	      makeAbsolute(result.getResultPoints(), 0, halfHeight);
80	      return result;
81	    } catch (NotFoundException re) {
82	      // continue
83	    }
84	
85	    try {
86	      Result result = delegate.decode(image.crop(halfWidth, halfHeight, halfWidth, halfHeight), hints);
87	      makeAbsolute(result.getResultPoints(), halfWidth, halfHeight);
88	      return result;
89	    } catch (NotFoundException re) {
90	      // continue
91	    }
92	
93	    int quarterWidth = halfWidth / 2;
94	    int quarterHeight = halfHeight / 2;
95	    BinaryBitmap center = image.crop(quarterWidth, quarterHeight, halfWidth, halfHeight);
96	    Result result = delegate.decode(center, hints);
97	    makeAbsolute(result.getResultPoints(), quarterWidth, quarterHeight);
98	    return result;
99	  }
100	
101	  @Override
102	  public void reset() {
103	    delegate.reset();
104	  }
105	
106	  private static void makeAbsolute(ResultPoint[] points, int leftOffset, int topOffset) {
107	    if (points != null) {
108	      for (int i = 0; i < points.length; i++) {
109	        ResultPoint relative = points[i];
110	        if (relative != null) {
111	          points[i] = new ResultPoint(relative.getX() + leftOffset, relative.getY() + topOffset);
112	        }    
113	      }
114	    }
115	  }
116	
117	}
