17	package com.google.zxing.datamatrix.detector;
18	
19	import com.google.zxing.NotFoundException;
20	import com.google.zxing.ResultPoint;
21	import com.google.zxing.common.BitMatrix;
22	import com.google.zxing.common.DetectorResult;
23	import com.google.zxing.common.GridSampler;
24	import com.google.zxing.common.detector.WhiteRectangleDetector;
25	
26	/**
27	 * <p>Encapsulates logic that can detect a Data Matrix Code in an image, even if the Data Matrix Code
28	 * is rotated or skewed, or partially obscured.</p>
29	 *
30	 * @author Sean Owen
31	 */
32	public final class Detector {
33	
34	  private final BitMatrix image;
35	  private final WhiteRectangleDetector rectangleDetector;
36	
37	  public Detector(BitMatrix image) throws NotFoundException {
38	    this.image = image;
39	    rectangleDetector = new WhiteRectangleDetector(image);
40	  }
41	
42	  /**
43	   * <p>Detects a Data Matrix Code in an image.</p>
44	   *
45	   * @return {@link DetectorResult} encapsulating results of detecting a Data Matrix Code
46	   * @throws NotFoundException if no Data Matrix Code can be found
47	   */
48	  public DetectorResult detect() throws NotFoundException {
49	
50	    ResultPoint[] cornerPoints = rectangleDetector.detect();
51	
52	    ResultPoint[] points = detectSolid1(cornerPoints);
53	    points = detectSolid2(points);
54	    points[3] = correctTopRight(points);
55	    if (points[3] == null) {
56	      throw NotFoundException.getNotFoundInstance();
57	    }
58	    points = shiftToModuleCenter(points);
59	
60	    ResultPoint topLeft = points[0];
61	    ResultPoint bottomLeft = points[1];
62	    ResultPoint bottomRight = points[2];
63	    ResultPoint topRight = points[3];
64	
65	    int dimensionTop = transitionsBetween(topLeft, topRight) + 1;
66	    int dimensionRight = transitionsBetween(bottomRight, topRight) + 1;
67	    if ((dimensionTop & 0x01) == 1) {
68	      dimensionTop += 1;
69	    }
70	    if ((dimensionRight & 0x01) == 1) {
71	      dimensionRight += 1;
72	    }
73	
74	    if (4 * dimensionTop < 6 * dimensionRight && 4 * dimensionRight < 6 * dimensionTop) {
75	      // The matrix is square
76	      dimensionTop = dimensionRight = Math.max(dimensionTop, dimensionRight);
77	    }
78	
79	    BitMatrix bits = sampleGrid(image,
80	                                topLeft,
81	                                bottomLeft,
82	                                bottomRight,
83	                                topRight,
84	                                dimensionTop,
85	                                dimensionRight);
86	
87	    return new DetectorResult(bits, new ResultPoint[]{topLeft, bottomLeft, bottomRight, topRight});
88	  }
89	
90	  private static ResultPoint shiftPoint(ResultPoint point, ResultPoint to, int div) {
91	    float x = (to.getX() - point.getX()) / (div + 1);
92	    float y = (to.getY() - point.getY()) / (div + 1);
93	    return new ResultPoint(point.getX() + x, point.getY() + y);
94	  }
95	
96	  private static ResultPoint moveAway(ResultPoint point, float fromX, float fromY) {
97	    float x = point.getX();
98	    float y = point.getY();
99	
100	    if (x < fromX) {

100	    if (x < fromX) {
101	      x -= 1;
102	    } else {
103	      x += 1;
104	    }
105	
106	    if (y < fromY) {
107	      y -= 1;
108	    } else {
109	      y += 1;
110	    }
111	
112	    return new ResultPoint(x, y);
113	  }
114	
115	  /**
116	   * Detect a solid side which has minimum transition.
117	   */
118	  private ResultPoint[] detectSolid1(ResultPoint[] cornerPoints) {
119	    // 0  2
120	    // 1  3
121	    ResultPoint pointA = cornerPoints[0];
122	    ResultPoint pointB = cornerPoints[1];
123	    ResultPoint pointC = cornerPoints[3];
124	    ResultPoint pointD = cornerPoints[2];
125	
126	    int trAB = transitionsBetween(pointA, pointB);
127	    int trBC = transitionsBetween(pointB, pointC);
128	    int trCD = transitionsBetween(pointC, pointD);
129	    int trDA = transitionsBetween(pointD, pointA);
130	
131	    // 0..3
132	    // :  :
133	    // 1--2
134	    int min = trAB;
135	    ResultPoint[] points = {pointD, pointA, pointB, pointC};
136	    if (min > trBC) {
137	      min = trBC;
138	      points[0] = pointA;
139	      points[1] = pointB;
140	      points[2] = pointC;
141	      points[3] = pointD;
142	    }
143	    if (min > trCD) {
144	      min = trCD;
145	      points[0] = pointB;
146	      points[1] = pointC;
147	      points[2] = pointD;
148	      points[3] = pointA;
149	    }
150	    if (min > trDA) {
151	      points[0] = pointC;
152	      points[1] = pointD;
153	      points[2] = pointA;
154	      points[3] = pointB;
155	    }
156	
157	    return points;
158	  }
159	
160	  /**
161	   * Detect a second solid side next to first solid side.
162	   */
163	  private ResultPoint[] detectSolid2(ResultPoint[] points) {
164	    // A..D
165	    // :  :
166	    // B--C
167	    ResultPoint pointA = points[0];
168	    ResultPoint pointB = points[1];
169	    ResultPoint pointC = points[2];
170	    ResultPoint pointD = points[3];
171	
172	    // Transition detection on the edge is not stable.
173	    // To safely detect, shift the points to the module center.
174	    int tr = transitionsBetween(pointA, pointD);
175	    ResultPoint pointBs = shiftPoint(pointB, pointC, (tr + 1) * 4);
176	    ResultPoint pointCs = shiftPoint(pointC, pointB, (tr + 1) * 4);
177	    int trBA = transitionsBetween(pointBs, pointA);
178	    int trCD = transitionsBetween(pointCs, pointD);
179	
180	    // 0..3
181	    // |  :
182	    // 1--2
183	    if (trBA < trCD) {
184	      // solid sides: A-B-C
185	      points[0] = pointA;
186	      points[1] = pointB;
187	      points[2] = pointC;
188	      points[3] = pointD;
189	    } else {
190	      // solid sides: B-C-D
191	      points[0] = pointB;
192	      points[1] = pointC;
193	      points[2] = pointD;
194	      points[3] = pointA;
195	    }
196	
197	    return points;
198	  }
199	
200	  /**
201	   * Calculates the corner position of the white top right module.
202	   */
203	  private ResultPoint correctTopRight(ResultPoint[] points) {
204	    // A..D
205	    // |  :
206	    // B--C
207	    ResultPoint pointA = points[0];
208	    ResultPoint pointB = points[1];
209	    ResultPoint pointC = points[2];
210	    ResultPoint pointD = points[3];
211	
212	    // shift points for safe transition detection.
213	    int trTop = transitionsBetween(pointA, pointD);
214	    int trRight = transitionsBetween(pointB, pointD);
215	    ResultPoint pointAs = shiftPoint(pointA, pointB, (trRight + 1) * 4);
216	    ResultPoint pointCs = shiftPoint(pointC, pointB, (trTop + 1) * 4);
217	
218	    trTop = transitionsBetween(pointAs, pointD);
219	    trRight = transitionsBetween(pointCs, pointD);
220	
221	    ResultPoint candidate1 = new ResultPoint(
222	        pointD.getX() + (pointC.getX() - pointB.getX()) / (trTop + 1),
223	        pointD.getY() + (pointC.getY() - pointB.getY()) / (trTop + 1));
224	    ResultPoint candidate2 = new ResultPoint(
225	        pointD.getX() + (pointA.getX() - pointB.getX()) / (trRight + 1),
226	        pointD.getY() + (pointA.getY() - pointB.getY()) / (trRight + 1));
227	
228	    if (!isValid(candidate1)) {
229	      if (isValid(candidate2)) {
230	        return candidate2;
231	      }
232	      return null;
233	    }
234	    if (!isValid(candidate2)) {
235	      return candidate1;
236	    }
237	
238	    int sumc1 = transitionsBetween(pointAs, candidate1) + transitionsBetween(pointCs, candidate1);
239	    int sumc2 = transitionsBetween(pointAs, candidate2) + transitionsBetween(pointCs, candidate2);
240	
241	    if (sumc1 > sumc2) {
242	      return candidate1;
243	    } else {
244	      return candidate2;
245	    }
246	  }
247	
248	  /**
249	   * Shift the edge points to the module center.
250	   */
251	  private ResultPoint[] shiftToModuleCenter(ResultPoint[] points) {
252	    // A..D
253	    // |  :
254	    // B--C
255	    ResultPoint pointA = points[0];
256	    ResultPoint pointB = points[1];
257	    ResultPoint pointC = points[2];
258	    ResultPoint pointD = points[3];
259	
260	    // calculate pseudo dimensions
261	    int dimH = transitionsBetween(pointA, pointD) + 1;
