279	    // I want points on the edges.
280	    float centerX = (pointA.getX() + pointB.getX() + pointC.getX() + pointD.getX()) / 4;
281	    float centerY = (pointA.getY() + pointB.getY() + pointC.getY() + pointD.getY()) / 4;
282	    pointA = moveAway(pointA, centerX, centerY);
283	    pointB = moveAway(pointB, centerX, centerY);
284	    pointC = moveAway(pointC, centerX, centerY);
285	    pointD = moveAway(pointD, centerX, centerY);
286	
287	    ResultPoint pointBs;
288	    ResultPoint pointDs;
