290	    // shift points to the center of each modules
291	    pointAs = shiftPoint(pointA, pointB, dimV * 4);
292	    pointAs = shiftPoint(pointAs, pointD, dimH * 4);
293	    pointBs = shiftPoint(pointB, pointA, dimV * 4);
294	    pointBs = shiftPoint(pointBs, pointC, dimH * 4);
295	    pointCs = shiftPoint(pointC, pointD, dimV * 4);
296	    pointCs = shiftPoint(pointCs, pointB, dimH * 4);
297	    pointDs = shiftPoint(pointD, pointC, dimV * 4);
298	    pointDs = shiftPoint(pointDs, pointA, dimH * 4);
