import com.google.zxing.Reader;
import com.google.zxing.Result;
import com.google.zxing.ResultPoint;

import java.util.Map;

/**
 * This class attempts to decode a barcode from an image, not by scanning the whole image,
 * but by scanning subsets of the image. This is important when there may be multiple barcodes in
 * an image, and detecting a barcode may find parts of multiple barcode and fail to decode
 * (e.g. QR Codes). Instead this scans the four quadrants of the image -- and also the center
 * 'quadrant' to cover the case where a barcode is found in the center.
 *
 * @see GenericMultipleBarcodeReader
 */
public final class ByQuadrantReader implements Reader {

  private final Reader delegate;

  public ByQuadrantReader(Reader delegate) {
    this.delegate = delegate;
  }

  @Override
  public Result decode(BinaryBitmap image)
      throws NotFoundException, ChecksumException, FormatException {
    return decode(image, null);
  }

  @Override
  public Result decode(BinaryBitmap image, Map<DecodeHintType,?> hints)
      throws NotFoundException, ChecksumException, FormatException {

    int width = image.getWidth();
    int height = image.getHeight();
    int halfWidth = width / 2;
    int halfHeight = height / 2;

    Result result;
    if ((result = tryDecode(image, hints, 0, 0, halfWidth, halfHeight)) != null) {
      return result;
    }
    if ((result = tryDecode(image, hints, halfWidth, 0, halfWidth, halfHeight)) != null) {
      return result;
    }
    if ((result = tryDecode(image, hints, 0, halfHeight, halfWidth, halfHeight)) != null) {
      return result;
    }
    if ((result = tryDecode(image, hints, halfWidth, halfHeight, halfWidth, halfHeight)) != null) {
      return result;
    }

    int quarterWidth = halfWidth / 2;
    int quarterHeight = halfHeight / 2;
    result = delegate.decode(image.crop(quarterWidth, quarterHeight, halfWidth, halfHeight), hints);
    makeAbsolute(result.getResultPoints(), quarterWidth, quarterHeight);
    return result;
  }

  @Override
  public void reset() {
    delegate.reset();
  }

  private Result tryDecode(BinaryBitmap image, Map<DecodeHintType,?> hints,
      int x, int y, int w, int h) throws ChecksumException, FormatException {
    try {
      Result result = delegate.decode(image.crop(x, y, w, h), hints);
      makeAbsolute(result.getResultPoints(), x, y);
      return result;
    } catch (NotFoundException re) {
      return null;
    }
  }

  private static void makeAbsolute(ResultPoint[] points, int leftOffset, int topOffset) {
    if (points == null || (leftOffset == 0 && topOffset == 0)) {
      return;
    }
    for (int i = 0; i < points.length; i++) {
      ResultPoint relative = points[i];
      if (relative != null) {
        points[i] = new ResultPoint(relative.getX() + leftOffset, relative.getY() + topOffset);
      }
    }
  }

