  /**
   * @return true iff nothing has been appended
   */
  public boolean isEmpty() {
    return currentBytes.length() == 0 && (result == null || result.length() == 0);
  }

  @Override
  public String toString() {
    encodeCurrentBytesIfAny();
    return result == null ? "" : result.toString();
  }
